const threadDescriptions = {
  ingrid_method_correctability:'Ingrid-tråden følger om senioritet brukes til å gjøre hypotesen mer korrigerbar eller mer beskyttet. Relasjonen starter med design som må kunne produsere et negativt resultat, går gjennom etikk, bestillerpress, kalibreringsavvik og fagfellekritikk, og ender med at sluttrapporten kan avgrenses uten at seniorens tidligere investering slettes. Spilleren bygger situert tillit hos Ingrid når uenighet, venting og rework blir synlige arbeidsformer; standing kan åpne tidligere metodehjelp, men kan aldri gjøre en konklusjon sann.',
  marius_field_traceability:'Marius-tråden følger feltarbeidets ofte lavere prestisje gjennom prøvespor, skiftende habitat, venting og senere analyse. Han husker om spilleren tok lokale avvik på alvor før de ble statistiske problemer og om feltteamets observasjoner fulgte handoff videre til lab og data. Tilliten er situert til feltintegritet: den kan gjøre neste innsamling mer samarbeidsvillig og informativ, men kan ikke gi forskerstatus, årsaksbevis eller forvaltningsmyndighet.',
  leila_lab_quality:'Leila-tråden følger laboratoriets kontroll- og stoppmakt fra første prøve til kalibreringsdrift og sluttrapport. Relasjonen tester om spilleren tåler at tekniske kontroller forsinker et prestisjefylt prosjekt, og om berørte prøver avgrenses uten å generalisere usikkerhet til hele serien eller skjule den. Hennes standing handler om kvalitetssamarbeid og tidlig varsling; den kan ikke velge prosjektets ønskede funn eller gi etikkgodkjenning.',
  noah_reproducibility:'Noah-tråden følger overgangen fra rådata til datasettversjoner, modellvalg, sensitivitet og replikasjon. Han husker om spilleren dokumenterte transformasjoner før et attraktivt estimat ble offentlig, og om en svakere replikasjon faktisk fikk endre språk og ny analyse. Situert tillit kan gjøre at Noah deler kontrollkode eller kobles inn tidligere, men statistisk standing kan aldri reparere svake data, gi kvalifikasjon eller gjøre modellprestasjon til politisk vedtak.',
  commissioner_boundary:'Bestillertråden følger den legitime spenningen mellom forskningens tidsbruk og en organisasjon som faktisk må handle. Amir presser på for klarhet ved mellomrapport og sluttrapport, mens spilleren må skille hva data støtter fra hva beslutningstaker ønsker å vite. Tillit hos bestiller bygges gjennom presis og brukbar usikkerhet, ikke gjennom sterkere språk. Den kan påvirke framtidige oppdrag og informasjonsflyt, men kan aldri fungere som evidens, etikkgodkjenning eller offentlig myndighet.',
  peer_review_correction:'Fagfelletråden følger hvordan ekstern kritikk kan gjøre lokale blindsoner og rivalforklaringer synlige. Sara møter prosjektet gjennom replikasjon, sensitivitetsanalyse og publiseringsfrist og undersøker om teamet kan korrigere argumentet uten å beskytte prestisje eller slette tidligere versjoner. Peer standing kan påvirke publiseringsløp, samarbeid og oppmerksomhet, men er fortsatt sosial og institusjonell tilgang — ikke sannhet, ansettelse eller garantist for at hypotesen er riktig.',
  private_research_identity:'Privattråden følger hvordan uavklart forskning, negativt resultat, korreksjon og synlig fagstatus lekker inn i identiteten etter arbeidsdagen. Den private relasjonen reagerer på om spilleren gjør hjemmet til en ekstra forsvarsscene eller kan være til stede uten å dele konfidensielle detaljer og uten å gjøre prosjektets verdi til mål på egen verdi. Dette er situert privat tillit, ikke profesjonell standing, og den kan aldri avgjøre metode, publisering, ansettelse eller etikk.'
};
for (const [threadId, refs] of Object.entries(threadRefs)) {
  for (const ref of refs) {
    const [dayText, phase] = ref.split('/');
    const beat = coverage.find((row) => row.day === Number(dayText) && row.phase === phase);
    if (!beat) throw new Error(`Missing beat for thread ${threadId}: ${ref}`);
    if (!beat.thread_ids.includes(threadId)) beat.thread_ids.push(threadId);
  }
}
world.season.coverage = coverage;
world.primary_threads = Object.entries(threadRefs).map(([id, beat_refs]) => ({ id, relationship: threadDescriptions[id], beat_refs }));
world.private_aftermath = [
  {id:'hypothesis_status_leakage',description:'Når en forhåndsregistrert hypotese blir en sosialt synlig identitet, kan spilleren komme hjem med behov for å forsvare prosjektet før dataene finnes. Etterklangen tester om personen kan skille entusiasme fra sannhet og la partner eller venn møte et uferdig menneske i stedet for en forsker som alltid må presentere en overbevisende tese. Konfidensielle prosjektopplysninger forblir avgrenset, og History Go- eller Natur-status får ikke bli privat bevis på kompetanse.',materialization_refs:[sourceRefs[0],sourceRefs[9]]},
  {id:'field_fatigue_and_invisible_work',description:'Feltarbeidets venting, vær, logistikk og prøvespor kan være lite synlig når resultatene senere blir figurer og rapport. Privat etterklang oppstår når spilleren er sliten av arbeid som institusjonen knapt ser, samtidig som Marius og feltteamet trenger at avvikene fortsatt tas alvorlig. Hjemme må spilleren kunne sette grenser for arbeidstid uten å late som status eller hastverk gjør feltdata mer komplette enn de er.',materialization_refs:[sourceRefs[1],sourceRefs[5]]},
  {id:'lab_stop_and_deadline_shame',description:'Når Leila stanser en prøveflyt eller kalibreringsdrift gjenåpner arbeid, kan prosjektet oppleves som personlig mislykket selv om stoppet er riktig kvalitetspraksis. Etterklangen gjør skammen konkret: spilleren må tåle tapt tempo og kanskje vanskelig kommunikasjon uten å flytte frustrasjonen over på laboratoriet eller privatlivet. Teknisk kvalitet, forskeridentitet og relasjonell verdi holdes atskilt.',materialization_refs:[sourceRefs[2],sourceRefs[10]]},
  {id:'replication_disappointment',description:'En svakere replikasjon kan gjøre det fristende å beskytte første resultat i samtaler med både kolleger og nære relasjoner. Privat etterklang undersøker om spilleren kan si at kunnskapen faktisk ble bedre selv om effekten ble mindre, og om det går an å avslutte dagen uten å gjøre korreksjon til tap av personlig verdi. Noahs analyse og Saras fagfellekritikk forblir profesjonelle kontrollflater, ikke dommer over personen.',materialization_refs:[sourceRefs[12],sourceRefs[6]]},
  {id:'publication_attention_boundary',description:'Når rapport eller manus nærmer seg publisering, kan ekstern oppmerksomhet, bestillerforventning og faglig status gjøre telefonen og prosjektet kontinuerlig til stede. Etterklangen tester om spilleren kan beskytte privat tid, la usikre spørsmål vente hos riktig eier og unngå å dele konfidensielle data for å få sosial bekreftelse. Publiseringsstanding og privat nærhet er forskjellige relasjoner og skal aldri summeres til en global score.',materialization_refs:[sourceRefs[14],sourceRefs[13]]}
];
